 @Override public boolean onDown(MotionEvent e){axis=PlayerGestureRules.NONE;seekStart=-1;seekTarget=-1;PlayerChrome.bump(a);if(blocked())return true;initialVolume=audio==null?0:audio.getStreamVolume(AudioManager.STREAM_MUSIC);int max=audio==null?0:audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);int boost=readBoost();startPercent=max<=0?0f:initialVolume*100f/max;allowBoost=max>0&&initialVolume>=max;if(allowBoost&&boost>100)startPercent=boost;float b=a.getWindow().getAttributes().screenBrightness;if(b<0)try{b=Settings.System.getInt(a.getContentResolver(),"screen_brightness")/255f;}catch(Exception ex){b=0.5f;}initialBrightness=b;return true;}
