 @Override public boolean onDoubleTap(MotionEvent e){if(blocked()){flashLock();return true;}int zone=PlayerGestureRules.third(e.getX(),width());if(zone==PlayerGestureRules.CENTER){if(FullscreenMode.doubleTapCenter(a))return true;if(!PlaybackPrefs.doubleTapCenter(a.getSharedPreferences("data",0))){controls(!controlsVisible());return true;}Object b=OnlineSubtitleSearch.field(a,"pauseButton");if(b instanceof View)((View)b).performClick();return true;}Object v=video();int dur=intCall(v,"getDuration"),pos=intCall(v,"getCurrentPosition");if(dur<=0||pos<0){FullscreenMode.hud(a,"等待视频准备完成");return true;}long now=android.os.SystemClock.elapsedRealtime();applyBurst(zone,PlayerGestureRules.burstDelta(zone,burstZone,burstDelta,now-burstAt,seekStep()),now);return true;}
