 TextView label(){TextView t=new TextView(a);t.setTextColor(0xffffffff);t.setTextSize(16);t.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);return t;}
 void showLevel(boolean brightness,int value,int scale){FrameLayout host=host();if(host==null)return;ui.removeCallbacks(hideLevel);if(levelHud==null){levelHud=new LinearLayout(a);levelHud.setOrientation(LinearLayout.HORIZONTAL);levelHud.setGravity(Gravity.CENTER_VERTICAL);levelHud.setPadding(dp(8),0,dp(8),0);GradientDrawable bg=new GradientDrawable();bg.setColor(0xcc1c1b22);bg.setCornerRadius(dp(8));levelHud.setBackground(bg);levelIcon=new TextView(a);levelIcon.setTextColor(0xffffffff);levelIcon.setTextSize(14);levelHud.addView(levelIcon,new LinearLayout.LayoutParams(dp(24),-2));FrameLayout track=new FrameLayout(a);GradientDrawable tray=new GradientDrawable();tray.setColor(0x55ffffff);tray.setCornerRadius(dp(8));track.setBackground(tray);levelFill=new View(a);levelFill.setBackgroundColor(0xffd7e7f5);levelExtra=new View(a);levelExtra.setBackgroundColor(0xffffb020);track.addView(levelFill,new FrameLayout.LayoutParams(0,dp(12),Gravity.CENTER_VERTICAL|Gravity.START));track.addView(levelExtra,new FrameLayout.LayoutParams(0,dp(12),Gravity.CENTER_VERTICAL|Gravity.START));levelHud.addView(track,new LinearLayout.LayoutParams(0,dp(12),1f));host.addView(levelHud,new FrameLayout.LayoutParams(dp(112),dp(32),Gravity.CENTER));}levelHud.setVisibility(View.VISIBLE);levelIcon.setText(brightness?"☀":value<=0?"🔇":"🔊");View track=(View)levelFill.getParent();int inner=Math.max(1,track.getWidth()>0?track.getWidth():dp(72));int primary=scale<=0?0:Math.round(inner*Math.min(value,100)/100f);int extra=value>100&&scale>100?Math.round(inner*Math.min(value-100,100)/100f):0;FrameLayout.LayoutParams fp=(FrameLayout.LayoutParams)levelFill.getLayoutParams();fp.width=Math.max(0,primary);levelFill.setLayoutParams(fp);FrameLayout.LayoutParams ep=(FrameLayout.LayoutParams)levelExtra.getLayoutParams();ep.width=Math.max(0,extra);levelExtra.setLayoutParams(ep);levelExtra.setVisibility(extra>0?View.VISIBLE:View.GONE);}
 final Runnable hideLevel=()->{if(levelHud!=null)levelHud.setVisibility(View.GONE);};
 void scheduleLevel(){if(levelHud==null||levelHud.getVisibility()!=View.VISIBLE)return;ui.removeCallbacks(hideLevel);ui.postDelayed(hideLevel,1000);}
 void hideLevel(){ui.removeCallbacks(hideLevel);if(levelHud!=null)levelHud.setVisibility(View.GONE);}
 FrameLayout host(){Object root=OnlineSubtitleSearch.field(a,"root");return root instanceof FrameLayout?(FrameLayout)root:null;}
 void buildLock(){Object root=OnlineSubtitleSearch.field(a,"root");if(!(root instanceof FrameLayout))return;lockButton=new Button(a);lockButton.setAllCaps(false);lockButton.setText("");lockButton.setBackground(PlayerOverlay.ripple(a));lockButton.setMinWidth(0);lockButton.setMinimumWidth(0);lockButton.setMinHeight(0);lockButton.setMinimumHeight(0);lockButton.setOnClickListener(v->toggleLock());FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(dp(40),dp(40),Gravity.START|Gravity.TOP);lp.leftMargin=dp(18);((FrameLayout)root).addView(lockButton,lp);lockButton.setVisibility(View.GONE);labelLock();}
 void labelLock(){if(lockButton==null)return;lockButton.setText("");int side=dp(PlayerLayoutMetrics.ICON_DP),touch=dp(PlayerLayoutMetrics.TOUCH_DP);PlayerIcons icon=new PlayerIcons(locked?PlayerIcons.LOCK:PlayerIcons.UNLOCK,side);icon.setBounds(0,0,side,side);int pad=Math.max(0,(touch-side)/2);lockButton.setCompoundDrawables(null,icon,null,null);lockButton.setPadding(pad,pad,pad,pad);lockButton.setGravity(Gravity.CENTER);lockButton.setContentDescription(locked?"解锁屏幕":"锁定屏幕");}
 final Runnable hideLock=()->{if(locked&&lockButton!=null)lockButton.setVisibility(View.GONE);};
 void flashLock(){if(lockButton==null)return;lockButton.setVisibility(View.VISIBLE);lockButton.setAlpha(1f);lockButton.removeCallbacks(hideLock);lockButton.postDelayed(hideLock,2500);}
 void toggleLock(){locked=!locked;labelLock();if(locked){PlayerSidePanel.close(a);controls(false);FullscreenMode.hud(a,"已锁定 · 点击屏幕显示解锁按钮");flashLock();}else{controls(true);FullscreenMode.hud(a,"已解锁");}}
